import { build } from 'esbuild';
import { createHash } from 'node:crypto';
import { readFile, realpath, readdir } from 'node:fs/promises';
import { isAbsolute, relative, resolve, sep } from 'node:path';
import { RUNTIME_FILES } from '../src/benchmark/study-schema.mjs';

const digest = bytes => createHash('sha256').update(bytes).digest('hex');
const portablePath = value => value.split(sep).join('/');

// Extension code and all its local dependencies become one pinned runtime file.
// Only actual core files are external: a plugin's own benchmark/registry.mjs
// must not accidentally resolve to the application's registry by basename.
export async function bundlePlugins({ root, entries, includeLean = true, runtimeEntries, externalRuntimeFiles = RUNTIME_FILES }) {
  runtimeEntries ??= includeLean ? [{ module: 'lean-plugin.mjs', export: 'leanBenchmark' }] : [];
  if (!Array.isArray(runtimeEntries) || runtimeEntries.some(entry => !/^[a-zA-Z0-9_-]+\.mjs$/.test(entry?.module) || !/^[a-zA-Z_$][a-zA-Z0-9_$]*$/.test(entry?.export))) {
    throw new Error('Runtime plugins require a local module filename and named descriptor export.');
  }
  root = await realpath(root);
  const inside = path => !isAbsolute(relative(root, path)) && !relative(root, path).split(sep).includes('..');
  if (!Array.isArray(entries) || entries.some(entry => typeof entry !== 'string' || !entry.startsWith('./') || !entry.endsWith('.mjs'))) {
    throw new Error('plugins.json must list local relative .mjs entry points.');
  }
  const normalized = [];
  for (const entry of entries) {
    const requested = resolve(root, entry);
    if (!inside(requested)) throw new Error('Plugin entry leaves the project directory: ' + entry);
    const path = await realpath(requested);
    if (!inside(path)) throw new Error('Plugin entry leaves the project directory: ' + entry);
    const name = './' + portablePath(relative(root, path));
    if (normalized.includes(name)) throw new Error('Plugin entry is listed twice: ' + entry);
    normalized.push(name);
  }
  const coreRoot = await realpath(resolve(root, 'src/benchmark'));
  const coreFiles = new Map(await Promise.all((await readdir(coreRoot)).filter(name => name.endsWith('.mjs') && externalRuntimeFiles.includes(name))
    .map(async name => [await realpath(resolve(coreRoot, name)), name])));
  const entryFiles = new Set(normalized.map(entry => resolve(root, entry)));
  const extension = await build({
    stdin: { contents: normalized.map(entry => `import ${JSON.stringify(entry)};`).join('\n'), resolveDir: root, sourcefile: 'configured-plugins.mjs' },
    absWorkingDir: root,
    bundle: true, write: false, metafile: true, format: 'esm', platform: 'browser', target: 'es2022', logLevel: 'silent',
    plugins: [{
      name: 'shared-core-contracts',
      setup(builder) {
        builder.onResolve({ filter: /^\.{1,2}\// }, async args => {
          let actual;
          const requested = resolve(args.resolveDir, args.path);
          if (!inside(requested)) throw new Error('Plugin dependency leaves the project directory: ' + args.path);
          try { actual = await realpath(requested); } catch { return; }
          if (!inside(actual)) throw new Error('Plugin dependency leaves the project directory: ' + args.path);
          const core = coreFiles.get(actual);
          if (core && !entryFiles.has(actual)) return { path: './' + core, external: true };
        });
      },
    }],
  });
  const sourceHashes = {};
  for (const name of Object.keys(extension.metafile.inputs).filter(name => name !== 'configured-plugins.mjs').sort()) {
    const actual = await realpath(resolve(root, name));
    if (!inside(actual)) throw new Error('Plugin dependency leaves the project directory: ' + name);
    sourceHashes[portablePath(relative(root, actual))] = digest(await readFile(actual));
  }
  const payload = extension.outputFiles[0].text;
  const metadata = { format: 'benchmark-plugin-package', version: 1, entries: normalized,
    runtimeEntries: runtimeEntries.map(entry => entry.module), sourceHashes, payloadSha256: digest(payload) };
  const record = JSON.stringify(metadata);
  const source = '// Generated by tools/plugin-bundle.mjs. Every byte travels in frozen exports.\n'
    + '// benchmark-plugin-package: ' + record + '\n'
    + 'import { registeredBenchmarks as __benchmarkPackageList, markPackagedBenchmarks as __benchmarkPackageMark } from "./registry.mjs";\n'
    + runtimeEntries.map((entry, index) => 'import { ' + entry.export + ' as __benchmarkPackageRuntime' + index + ' } from "./' + entry.module + '";\n').join('')
    + 'const __benchmarkPackageBefore = new Set(__benchmarkPackageList());\n'
    + '// benchmark-plugin-payload-begin\n' + payload + '// benchmark-plugin-payload-end\n'
    + '__benchmarkPackageMark([' + runtimeEntries.map((_, index) => '__benchmarkPackageRuntime' + index + ', ').join('') + '...__benchmarkPackageList().filter(entry => !__benchmarkPackageBefore.has(entry))], ' + record + ');\n'
    + 'export { registeredBenchmarks, benchmarkFor, extractionPolicyFor } from "./registry.mjs";\n';
  return { source, metadata };
}
